export const presets = definitions.map(([name, mode, values], index) => ({
  id: `factory-${index}`, name, mode, values: Object.fromEntries(order.map((id, i) => [id, values[i]])),
}));
export function validatePreset(preset) {
  return preset && typeof preset.name === 'string' && preset.name.trim().length > 0 && preset.name.length <= 60
    && typeof preset.id === 'string' && Number.isInteger(preset.mode) && preset.mode >= 0 && preset.mode < 8
    && parameterList.every(([id, , min, max]) => Number.isFinite(preset.values?.[id]) && preset.values[id] >= min && preset.values[id] <= max);
}
